(function(){"use strict";function googleUrl(frame){try{var url=new URL(frame.getAttribute("src")||"",location.href);return/^(www\.)?google\.com$|^maps\.google\.com$/.test(url.hostname)&&/^\/maps(?:\/|$)/.test(url.pathname)?url.href:""}catch(_){return""}}function retry(frame){var url=googleUrl(frame);if(!url)return;var fresh=frame.cloneNode(false);fresh.removeAttribute("data-google-recovery");fresh.loading="eager";frame.replaceWith(fresh);attach(fresh)}function attach(frame){var url=googleUrl(frame);if(!url||frame.dataset.googleRecovery)return;frame.dataset.googleRecovery="1";var parent=frame.parentElement;if(!parent)return;parent.classList.add("has-google-frame");var bar=parent.querySelector(":scope > .google-frame-recovery");if(!bar){bar=document.createElement("div");bar.className="google-frame-recovery";bar.addEventListener("click",function(event){event.stopPropagation()});parent.appendChild(bar)}var button=document.createElement("button");button.type="button";button.textContent="↻ Znovu načíst";button.setAttribute("aria-label","Znovu načíst "+(frame.title||"Google mapu"));button.addEventListener("click",function(){retry(frame)});var link=document.createElement("a");link.href=url;link.target="_blank";link.rel="noopener noreferrer";link.textContent="Otevřít samostatně ↗";bar.replaceChildren(button,link)}function scan(scope){if(scope.matches&&scope.matches("iframe"))attach(scope);if(scope.querySelectorAll)scope.querySelectorAll("iframe").forEach(attach)}function init(){scan(document);new MutationObserver(function(changes){changes.forEach(function(change){change.addedNodes.forEach(function(node){if(node.nodeType===1)scan(node)})})}).observe(document.body,{childList:true,subtree:true})}window.addEventListener("bali:maps-retry",function(){document.querySelectorAll("iframe").forEach(function(frame){if(googleUrl(frame)&&frame.getBoundingClientRect().height&&!frame.closest("[inert]"))retry(frame)})});if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init()})();